local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end
local hooks,timers={},{};local hookapi={Add=function(e,n,f)hooks[e.."/"..n]=f end,Remove=function(e,n)hooks[e.."/"..n]=nil end,Run=function(e,...)local f=hooks[e.."/RheniumPropAlignment.CanTool"];if f then return f(...)end end};local timerapi={Create=function(n,d,r,f)timers[n]=f end,Remove=function(n)timers[n]=nil end}
local function valid(x)return type(x)=="table"and x.valid~=false end;local function player()return{valid=true,IsPlayer=function()return true end}end
local function vec(x,y,z)local v={x=x,y=y,z=z};function v:AngleEx()return{x=self.x,y=self.y,z=self.z}end;return v end
local function entity()local e={valid=true,pos=vec(0,0,0),ang=vec(0,0,0),model="m",class="prop_physics"};function e:GetPos()return self.pos end;function e:GetAngles()return self.ang end;function e:GetModel()return self.model end;function e:GetClass()return self.class end;function e:GetPhysicsObject()return{valid=false}end;function e:SetModel(v)self.model=v end;function e:SetPos(v)self.pos=v end;function e:SetAngles(v)self.ang=v end;function e:Spawn()end;function e:Activate()end;function e:Remove()self.valid=false end;return e end
local made={};local entsapi={Create=function()local e=entity();made[#made+1]=e;return e end};local constraintapi={Weld=function()local e=entity();made[#made+1]=e;return e end};local undo_function=nil;local undoapi={Create=function()undo_function=nil end,AddEntity=function()end,AddFunction=function(f,...)undo_function={f=f,args={...}}end,SetPlayer=function()end,Finish=function()return true end}
local bindings;local function include(p)if p=="rhenium_prop_alignment/alignment.lua"then return load_submission("lua/rhenium_prop_alignment/alignment.lua",bindings)end;return load_submission("lua/rhenium_prop_alignment/server.lua",bindings)end
bindings={include=include,hook=hookapi,timer=timerapi,IsValid=valid,ents=entsapi,constraint=constraintapi,undo=undoapi,Vector=vec};local S=load_submission("lua/rhenium_prop_alignment/server.lua",bindings)
local p,e=player(),entity()
case("adapter installs CanTool lifecycle hooks and timer",function()S.Install({});assert(hooks["CanTool/"..S.HookPrefix..".CanTool"]);assert(hooks["PlayerDisconnected/"..S.HookPrefix..".Disconnect"]);assert(timers[S.TimerName])end)
case("trusted player and entity bindings drive six traces",function()assert(S.BindPlayer(p,"A"));assert(S.BindEntity(e,"prop:1",1));local pts={vec(0,0,0),vec(10,0,0),vec(0,10,0),vec(100,20,30),vec(100,30,30),vec(90,20,30)};for _,v in ipairs(pts)do local ok,c=S.HandleTrace(p,{Hit=true,HitPos=v,Entity=e});assert(ok,c)end end)
case("unbound and forged trace identity are rejected",function()local q=player();local ok,c=S.HandleTrace(q,{Hit=true,HitPos=vec(0,0,0),Entity=e});assert(not ok and c=="invalid_trace")end)
case("CanTool denial blocks staging before mutation",function()local f=hooks["CanTool/"..S.HookPrefix..".CanTool"];hooks["CanTool/"..S.HookPrefix..".CanTool"]=function()return false end;local q,e2=player(),entity();assert(S.BindPlayer(q,"B"));assert(S.BindEntity(e2,"prop:2",1));local ok,c=S.HandleTrace(q,{Hit=true,HitPos=vec(0,0,0),Entity=e2});assert(not ok and c=="permission_denied");hooks["CanTool/"..S.HookPrefix..".CanTool"]=f end)
case("execute creates one constrained copy and one undo unit",function()local ok,c,d=S.Execute(p,e,"go","copy");assert(ok,c);assert(#d.created==2 and #made==2)end)
case("move changes original without clone and undo restores transform",function()local q,e2=player(),entity();assert(S.BindPlayer(q,"M"));assert(S.BindEntity(e2,"prop:m",1));local pts={vec(0,0,0),vec(1,0,0),vec(0,1,0),vec(5,0,0),vec(5,1,0),vec(4,0,0)};for _,v in ipairs(pts)do assert(S.HandleTrace(q,{Hit=true,HitPos=v,Entity=e2}))end;local before=#made;local ok,c=S.Execute(q,e2,"move","move");assert(ok,c);assert(#made==before and e2.pos.x==5 and undo_function);undo_function.f({Name="mock undo"},undo_function.args[1],undo_function.args[2],undo_function.args[3]);assert(e2.pos.x==0);for _,v in ipairs(pts)do assert(S.HandleTrace(q,{Hit=true,HitPos=v,Entity=e2}))end;local again,again_code=S.Execute(q,e2,"move-again","move");assert(again,again_code)end)
case("unknown execution mode is rejected before core mutation",function()local ok,c=S.Execute(p,e,"unknown","teleport");assert(not ok and c=="invalid_mode")end)
case("constraint failure rolls back created entities",function()local old=constraintapi.Weld;constraintapi.Weld=function()return{valid=false}end;local q=player();local e2=entity();assert(S.BindPlayer(q,"C"));assert(S.BindEntity(e2,"prop:3",1));local pts={vec(0,0,0),vec(1,0,0),vec(0,1,0),vec(2,0,0),vec(2,1,0),vec(1,0,0)};for _,v in ipairs(pts)do assert(S.HandleTrace(q,{Hit=true,HitPos=v,Entity=e2}))end;local before=#made;local ok,c=S.Execute(q,e2,"bad","copy");assert(not ok and c=="constraint_failed");assert(#made==before+1 and made[#made].valid==false);constraintapi.Weld=old end)
case("disconnect clears adapter staging identity",function()hooks["PlayerDisconnected/"..S.HookPrefix..".Disconnect"](p);assert(true)end)
case("shutdown removes every hook and timer",function()S.Shutdown();S.Shutdown();for k in pairs(hooks)do if k:find("RheniumPropAlignment",1,true)then error("hook leak")end end;assert(not timers[S.TimerName])end)
return{cases=cases}
